import sys


def is_prime(n):
    if n < 2:
        return False
    d = 2
    while d * d <= n:
        if n % d == 0:
            return False
        d += 1
    return True


def main():
    data = sys.stdin.read().split()
    q = int(data[0])
    out = []
    for k in range(q):
        l = int(data[1 + 2 * k])
        r = int(data[2 + 2 * k])
        cnt = 0
        for x in range(l, r + 1):
            if is_prime(x):
                cnt += 1
        out.append(str(cnt))
    print('\n'.join(out))


main()
